type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

interface Entity { id: string; }

function processEntity<T extends Entity>(
  entity: T,
  validate: (e: T) => string | null
): Result<T, string> {
  const error = validate(entity);
  return error ? { ok: false, error } : { ok: true, value: entity };
}

interface Order extends Entity { totalCents: number; }

const outcome = processEntity<Order>(
  { id: 'ORD-1', totalCents: -50 },
  order => (order.totalCents < 0 ? 'Montant négatif invalide' : null)
);

if (!outcome.ok) {
  console.error(outcome.error);
}

